In JavaScript, you handle runtime errors using try/catch/finally blocks. The `try` block contains code that might throw an error, the `catch` block handles the error, and the `finally` block runs regardless of whether an error occurred:

```javascript
// Basic try/catch
try {
  // Code that might throw an error
  const result = someUndefinedFunction();
  console.log(result);
} catch (error) {
  // Handle the error
  console.error('An error occurred:', error.message);
} finally {
  // Always runs
  console.log('This always executes');
}

// With specific error types
try {
  const data = JSON.parse(invalidJson);
} catch (error) {
  if (error instanceof SyntaxError) {
    console.error('Invalid JSON:', error.message);
  } else if (error instanceof TypeError) {
    console.error('Type error:', error.message);
  } else {
    console.error('Unknown error:', error);
  }
}

// Async/await with try/catch
async function fetchData() {
  try {
    const response = await fetch('/api/data');
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Fetch failed:', error);
    throw error; // Re-throw if caller needs to handle it
  }
}

// Custom errors
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

try {
  throw new ValidationError('Invalid input');
} catch (error) {
  if (error instanceof ValidationError) {
    console.error('Validation failed:', error.message);
  }
}
```

Always use try/catch around code that can throw: JSON.parse(), fetch() calls, file operations, and any code using throw statements. The `finally` block is useful for cleanup operations like closing connections or hiding loading spinners.
